min_mutation(StartGene, EndGene, Bank) -> mutation_bfs([StartGene], EndGene, lists:delete(StartGene, Bank), 0). mutation_bfs([], _, _, _) -> -1; mutation_bfs(Front, End, Bank, Steps) -> case lists:member(End, Front) of true -> Steps; false -> Next = [G || G <- Bank, lists:any(fun(F) -> length([1 || {A,B} <- lists:zip(binary_to_list(F), binary_to_list(G)), A =/= B]) =:= 1 end, Front)], mutation_bfs(Next, End, Bank -- Next, Steps + 1) end.
